def compute(vars):
    values = [vars["v1"], vars["v2"]]
    result = max(values)
    return {
        "value": result,
        "trace": {
            "values": values,
            "maximum": result,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
